/**
 * Generated by scaffold-listing-primitives. `data-component="bulk-actions"`.
 *
 * The bar that appears once at least one row is selected. Renders nothing at
 * zero, so it never occupies layout on a freshly loaded listing.
 *
 * Usage:
 *   <BulkActions
 *     testId="user-list"
 *     count={sel.count}
 *     onClear={sel.clear}
 *     actions={[{ label: 'Delete', destructive: true, onSelect: () => bulkDelete(sel.selected) }]}
 *   />
 */
import { useTranslation } from 'react-i18next';

export interface BulkAction {
  label: string;
  onSelect: () => void | Promise<void>;
  destructive?: boolean;
  disabled?: boolean;
}

export interface BulkActionsProps {
  testId: string;
  count: number;
  actions: BulkAction[];
  onClear?: () => void;
  /** Blocks the buttons while a bulk request is in flight. */
  busy?: boolean;
}

export function BulkActions({ testId, count, actions, onClear, busy }: BulkActionsProps) {
  const { t } = useTranslation('common');
  if (count <= 0 || actions.length === 0) return null;

  return (
    <div className="bulk-bar" role="region" aria-live="polite" data-testid={testId + '-bulk-bar'}>
      <span className="bulk-count" data-testid={testId + '-bulk-count'}>
        {t('actions.selectedCount', { count, defaultValue: '{{count}} selected' })}
      </span>
      <div className="bulk-bar-actions">
        {actions.map((a) => (
          <button
            key={a.label}
            type="button"
            className={a.destructive ? 'is-destructive' : undefined}
            disabled={a.disabled || busy}
            onClick={() => a.onSelect()}
            data-testid={testId + '-bulk-' + a.label.toLowerCase().replace(/\s+/g, '-')}
          >
            {a.label}
          </button>
        ))}
        {onClear && (
          <button type="button" onClick={onClear} disabled={busy} data-testid={testId + '-bulk-clear'}>
            {t('actions.clear', { defaultValue: 'Clear' })}
          </button>
        )}
      </div>
    </div>
  );
}
